custom_css:
/*! 
 * Theme: 格纹-粉
 * Author: endlessrefrain
 * 当前版本: 1.0.0 | 最后更新: 2026-04-06
 */

/*! 本美化仅限个人自用，请勿无授权二传二改，代码参考/借鉴(即使只是部分)请注明出处 */

/*! 禁止用于任何商业化用途，贩子死全家 */

/* 字体颜色请调整在自带的主题颜色里修改:
引用文本➡️“对话”颜色
下划线文本➡️对话背景色、行内代码块背景色
斜体文本➡️斜体字下划线 */

/*! ======= 变量定义 ======= */
:root {
  --最新回复与输入框距离: 80px;
  --输入框文字: "₊┈𓏴𓏴₊-୨♡୧-₊𓏴𓏴┈₊";

  /* 黑粉格纹 */
  --pattern-1: url('https://files.catbox.moe/zpaqry.jpg');
  /* 粉白格纹(用黑粉就把下面这行代码删掉，或者用注.释符号包起来，不懂就问ai) */
  --pattern-1: url('https://files.catbox.moe/484sq2.png');

   --顶栏图标大小: 1.1em;
  /*顶栏图标→用记忆表格的话把icon-1的数字改成2，2改成1 */
  --icon-1: url('https://files.catbox.moe/m0zu5s.png');
  --icon-2: url('https://files.catbox.moe/sc7acq.png');

  --pattern-2: url('https://files.catbox.moe/hb2gys.jpg');
  --color-1: rgba(255, 253, 253, 1);
  --color-2: rgba(214, 214, 214, 1);
  --color-3: rgba(255, 216, 230, 1);
  --shadow-1: rgba(77,77,77,0.25);
}

/*! ======= 通用设置 ======= */
/* 滚动条 */
::-webkit-scrollbar {
  width: 4px;
}

::-webkit-scrollbar-thumb {
  background:  var(--color-3) !important;
  border-radius: 0px !important;
  border:  none  !important;
  box-shadow: none !important;
}

body {
  --black30a: #fff;
  --avatar-base-border-radius: 0;
}

#chat .mes {
  transform: translateZ(0);
  will-change: transform;
}

body .avatar img {
  border: none;
  box-shadow: none;
  border-radius: 0 !important;
}

/*! ======= 顶栏 ======= */
#top-bar, 
body.no-blur #top-bar {
  background: var(--pattern-1) center / 80px auto repeat !important;
  width: calc(100% - 0.5rem);
  border-radius: 0 0 8px 8px;
  outline: 2px solid var(--color-1);
  box-shadow: 1px 2px 0 1.5px var(--color-2);
}

#extensionTopBar {
  z-index: 99;
  width: calc(100% - 1rem) !important;
  align-self: center !important;
  transform: translateY(5px);
  border-radius: 8px !important;
  border: 1.2px solid var(--color-1) !important;
  box-shadow:
    inset 1px 1px 1.5px rgba(0,0,0,0.25),
    inset 0 0 2px rgba(0,0,0,0.15),
    0.5px 1px 0 0.5px var(--color-2);
}

/* 顶栏图标 */
.drawer-icon.fa-fw {
  display: flex;
  justify-content: center;
  align-items: center;
  overflow: visible;
  position: relative;
  z-index: 1;
  height: var(--顶栏图标大小);
  width: var(--顶栏图标大小);
  background-size: contain;
  background-repeat: no-repeat;
  background-position: center;
  filter: none !important;
  transition: all 0.4s ease;
  opacity: 1;
  border-radius: 0;
  &::before {
    display: none;
  }
}

.drawer-icon { 
  background-image: url('https://files.catbox.moe/sc7acq.png');
}

#sys-settings-button .drawer-icon,
#WI-SP-button .drawer-icon,
#logo_block .drawer-icon,
#backgrounds-drawer-toggle .drawer-icon,
#table_database_settings_drawer .drawer-icon,
#rightNavHolder .drawer-icon { 
  background-image: url('https://files.catbox.moe/m0zu5s.png');
}

#sys-settings-button:has(.redOverlayGlow) .drawer-icon {
  filter: saturate(0) !important;
}

#persona-management-button .drawer-icon { 
  background-image: var(--icon-1);
}
#rightNavHolder .drawer-icon{ 
  background-image: var(--icon-2);
}

/*! ======= 底部输入框  ======= */
#form_sheld {
  position: absolute;
  bottom: 5px;
}

#send_form, 
body.no-blur #send_form {
  width: calc(100% - 1rem);
  transform: translateY(-5px);
  padding: 5px !important;
  border-radius: 20px;
  background: var(--pattern-1) center / 80px auto repeat !important;
  outline: 2px solid var(--color-1) !important;
  box-shadow: 1px 2px 0 2px var(--color-2);
}

/* 底部图标 */
#options_button::before,
#extensionsMenuButton::before,
#send_but::before,
#quick-reply-rocket-button > i {
  display: none;
}

#options_button,
#extensionsMenuButton,
#send_but,
#quick-reply-rocket-button {
  opacity: 1 !important;
  background: url('https://files.catbox.moe/fwk0ur.png') center / contain no-repeat;
}

#send_textarea {
  &::placeholder {
    opacity: 0;
  }
  clip-path: none;
  border: 1.2px solid var(--color-1);
  border-radius: 10px;
  background: var(--pattern-2) center / 200% auto no-repeat;
  box-shadow:
    inset 1px 1px 1.5px rgba(0,0,0,0.25),
    inset 0 0 2px rgba(0,0,0,0.15),
    0.5px 1px 0 0.5px var(--color-2);
}

#nonQRFormItems {
  display: flex;
  position: relative;
  align-items: center;
  &::before {
    content: var(--输入框文字);
    display: none;
    position: absolute;
    left: calc(50% + 15px);
    top: 50%;
    transform: translate(-50%, -50%);
    font-size: calc(var(--mainFontSize) * 0.85);
    color: var(--SmartThemeEmColor);
    pointer-events: none;
    z-index: 1;
  }
}

#nonQRFormItems:has(#send_textarea:not(:focus):placeholder-shown)::before {
  display: block;
}

/* by咩野 */
#form_sheld:has(#send_textarea:focus),
#form_sheld:has(#send_textarea:not(:placeholder-shown)) {
  position: static;
}

/* --- qr --- */
#qr--bar {
  display: none !important;
  /*overflow: visible !important;
  align-items: center !important;*/
}

#send_form:focus-within #qr--bar {
  display: flex !important;
}

#qr--bar > .qr--buttons .qr--button {
  opacity: 1 !important;
  &:hover {
    background: #fff !important;
  }
  &:active {
    box-shadow: inset 0 2px 5px rgba(0, 0, 0, 0.2) !important;
  }
}

.list-group,
.options-content,
#options,
#quickPersonaImg {
  box-shadow: none !important;
}

.list-group-item .quickPersonaMenuImg {
  box-shadow: none;
  border: none;
}

/*! ======= 抽屉菜单 ======= */
body .drawer-content.openDrawer {
  border: none;
  top: var(--bottomFormBlockSize);
  background: var(--pattern-2) center / cover no-repeat;
}

@media (max-width: 768px) {
  #left-nav-panel,
  #right-nav-panel {
    top: var(--bottomFormBlockSize) !important;
  }
  #left-nav-panel {
    padding-right: 0;
  }
}

.reverse_proxy_warning {
  border-color: crimson !important;
  border-radius: 2px !important;
  background-color: var(--color-1) !important;
}

/* 大标题 */
.standoutHeader,
.inline-drawer-header,
#user-settings-block h4,
#rm_extensions_block .inline-drawer-toggle.inline-drawer-header {
  position: relative;
  margin-bottom: 10px;
  padding: 2px 5px !important;
  background: url('https://files.catbox.moe/hb2gys.jpg') center / 300px auto repeat;
  border-radius: 1px;
  border: none;
  &::before {
    content: '';
    position: absolute;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: calc(100% + 5px);
    height: calc(100% + 5px);
    border-radius: inherit;
    /*background: url('https://files.catbox.moe/cktrr6.jpg') center / 100px auto repeat;*/
    background-color: var(--color-3);
    z-index: -1;
    box-shadow: 1px 1px 1px var(--shadow-1);
  }
  &:hover {
    filter: none;
  }
}

.inline-drawer-icon {
  filter: none;
  font-size: 1.75em;
  color: transparent;
  background: url("https://files.catbox.moe/wv5h2w.png") center / contain no-repeat;
}

.inline-drawer-icon.fa-circle-chevron-up {
  filter: hue-rotate(265deg);
}

/* 下拉 & 输入框 & 按钮 */
input:not([type]),
input[type="text"],
input[type="search"],
input[type="number"],
textarea.text_pole,
textarea.textarea_compact,
textarea:not(#send_textarea),
.menu_button,
select:not(#extensionTopBarChatName),
select.text_pole {
  background: #fff;
  border-radius: 1px;
  border: 1px solid var(--color-2);
  outline: 1px solid var(--color-1) !important;
  box-shadow: 1px 1px 2px var(--shadow-1);
  &:hover {
    outline: none;
  }
}

.menu_button {
  &:hover {
    color: var(--color-3) !important;
    background: #fff !important;
    border: 1px solid var(--color-3) !important;
    filter: none !important;
  }
}

#bulkDeleteButton,
#delete_button,
#persona_delete_button,
#world_popup_delete,
.menu_button.popup-button-ok,
#delete_connection_profile,
#delete_oai_preset,
#dialogue_del_mes_ok,
.mes_edit_cancel.menu_button,
.mes_edit_buttons .mes_edit_delete {
  --红: rgba(255, 15, 15, 1);
  background: #fff !important;
  border-color: var(--红) !important;
  color: var(--红) !important;
}

/* 滑动条 */
input[type="range"] {
  background: var(--color-3) !important;
  filter: none !important;
  box-shadow: 1px 1px 2px var(--shadow-1);
}

#wiTopBlock input[type="range"],
#user-settings-block input[type="range"] {
  border-radius: 1px !important;
  box-shadow: inset 0 0 1px var(--shadow-1) !important;
}

input[type="range"]::-webkit-slider-thumb {
  width: 32px;
  height: 32px; 
  background: url('https://files.catbox.moe/fwk0ur.png') center / contain no-repeat;
  background-color: transparent !important;
  border: none;
}

#tag_import_setting {
  margin-top: 5px;
}

#UI-presets-block {
  padding-top: 5px;
  gap: 5px;
}

div[name="themeElements"] > div.inline-drawer.wide100p > div.inline-drawer-toggle.inline-drawer-header {
  margin-top: 8px;
}

/* 勾选 */
input[type="checkbox"] {
  background: transparent;
  border-radius: 0;
  filter: none;
  border: 1px solid var(--color-2);
  outline: 1px solid var(--color-1) !important;
  box-shadow:
    0 0 1px var(--shadow-1),
    1px 1px 1px var(--shadow-1) !important;
}

.checkbox_label {
  display: flex;
  align-items: center;
}

input[type="checkbox"]:checked {
  background:  color-mix(in srgb, var(--color-3) 75%, transparent) !important;
}

/* 弹窗 */
#select_chat_popup,
.popup:not(.transparent_dialogue_popup) {
  background: var(--pattern-2) center / cover repeat;
  box-shadow:
    0 0 8px var(--color-3),
    1px 1px 5px var(--color-3);
  border-radius: 0;
  border: 1px solid var(--color-2);
  outline: 1.5px solid var(--color-1);
}

.toast {
  border-radius: 0 !important;
  outline: 1.5px solid var(--SmartThemeBlurTintColor);
  color: var(--SmartThemeBodyColor) !important;
  box-shadow:
    1px 1px 5px var(--shadow-1),
    0 0 6px var(--shadow-1) !important;
}

div.toast.toast-success {
  background-color: #cae69e !important;
}

div.toast.toast-error {
  background-color: #e6655f !important;
  color: #000 !important;
}

div.toast.toast-info {
  background-color: #cdecff !important;
}

.popup-content:has(#showRawPrompt) {
  overflow-y: auto;
}

/*! ======= 左侧导航 ====== */
.range-block > .toggle-description {
  margin-right: 0;
}

.range-block-title {
  text-align: left;
}

/* by kakaa */
label[for="openai_image_inlining"] + div,
#openai_settings .inline-drawer-header .flex-container {
  gap: 0;
  line-height: 1.2;
}

#openai_settings .inline-drawer-header .flex-container b {
  margin: 1px 3px 1px 0;
}

#openai_settings .flex-container.oneline-dropdown {
  align-items: center;
  gap: 0;
}

#openai_verbosity {
  order: 1;
}

#completion_prompt_manager_list {
  background: var(--color-1);
  padding: 0 8px;
  border-radius: 0;
  border: 1.5px solid var(--color-2);
  outline: 1.5px solid var(--color-1);
  box-shadow:
    0px 0px 5px var(--shadow-1),
    1px 1px 3px var(--shadow-1);
}

.completion_prompt_manager_header,
.completion_prompt_manager_footer {
  padding: 0 !important;
}

.completion_prompt_manager_header * {
  color: var(--SmartThemeBodyColor);
  filter: none  !important;
  margin-left: 0 !important;
}

.prompt_manager_prompt_controls > span {
  filter: none !important;
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt {
  background: var(--color-1);
  border: 1px solid var(--color-3);
  outline: 1px solid var(--color-1);
  box-shadow: 1px 1px 2px var(--shadow-1);
}

#completion_prompt_manager #completion_prompt_manager_list li.completion_prompt_manager_prompt_disabled {
  background: var(--color-1);
  border: 1px solid var(--color-2) !important;
  opacity: 0.5;
}

.completion_prompt_manager_prompt_disabled .completion_prompt_manager_prompt_name a {
  color: var(--SmartThemeBodyColor) !important;
  text-decoration: line-through;
}

/* 世界书 */
.world_entry {
  margin-top: 20px;
}

.wi-card-entry {
  border: none;
  border-radius: 5px;
}

#wiTopBlock .inline-drawer.wide100p .inline-drawer-content {
  background: var(--SmartThemeBlurTintColor) !important;
  border-radius: 0;
  margin-top: 5px;
}

#wiTopBlock .standoutHeader {
  margin-top: 5px;
}

/* 图库 */
#bg_tabs,
#bg_chat_tab,
#bg_global_tab {
  border: none !important;
  box-shadow: none;
}

.bg_example {
  border-radius: 0;
  box-shadow: none !important;
}

.BGSampleTitle {
  background: none !important;
}

.mobile-only-menu-toggle,
.jg-menu {
  transform: scale(0.75) !important;
  opacity: 0.5;
}

/* 扩展页 */
@media (hover: none) and (pointer: coarse) {
  .regex-script-label {
    pointer-events: none;
  }

  .regex-script-label > *:not(.regex_script_name) {
    pointer-events: auto;
  }

  .regex-script-label .drag-handle {
    pointer-events: auto;
    padding: 3px;
  }
}

#regex_container {
  .regex-script-label {
    background: var(--SmartThemeBlurTintColor);
    outline: 1.2px solid var(--SmartThemeBlurTintColor);
    border-radius: 0px;
    box-shadow:
    1px 1px 2px var(--shadow-1),
    0 0 2px var(--shadow-1);
  }

  .regex-script-label:has(.disable_regex:not(:checked)) {
    border-color: var(--color-3);
    .menu_button.interactable {
      border-color: var(--color-3);
      opacity: 1;
      filter: none;
    }
  }

  .regex_script_name {
    white-space: normal;
  }

  .regex-script-label.flex-container {
    align-items: center;
  }

  .regex-toggle-on {
    color: var(--color-3);
  }
}

/* 用户页 */
#persona_controls.flex-container label.flex1 {
  flex-basis: 100%;
  width: 100%;
}

/*! ======= 右侧导航 ======= */
.character_select {
  margin-top: 0.5rem;
}

#avatar_div .avatar,
#rm_print_characters_block .avatar,
#user_avatar_block .avatar {
  position: relative;
  &::before {
    content: '';
    position: absolute;
    aspect-ratio: 1/1;
    width: calc(100% + 8px);
    height: auto;
    left: 50%;
    top: calc(50% - 1px);
    transform: translate(-50%, -50%);
    background: url('https://files.catbox.moe/80ua2e.png') center / contain no-repeat;
  }
}

#user_avatar_block .avatar-container.selected,
.character_select.is_fav {
  background: var(--color-1);
  border-radius: 0;
  outline: 1.2px solid var(--color-1);
  border: 1.2px solid var(--color-3);
  box-shadow:
    0px 0px 2px var(--shadow-1),
    1px 1px 2px var(--shadow-1);
  .avatar {
  outline: none;
  }
  .ch_name {
  color: var(--color-3);
  }
}

#rm_button_characters {
  font-size: calc(var(--mainFontSize) * 1.25);
}

#HotSwapWrapper {
  overflow: hidden;
}

.avatars_inline {
  gap: 3px;
  flex-wrap: nowrap;
  overflow: visible;
}

#HotSwapWrapper > div {
  overflow: auto hidden; 
  flex-wrap: nowrap;
  max-height: calc(var(--avatar-base-height) * 2);
  &::-webkit-scrollbar {
    display: none;
  }
}

.search-wrapper {
  background: var(--pattern-2) center/cover repeat !important;
  .search-input {
    border: 1px solid var(--color-3) !important;
    outline: 1px solid var(--color-1) !important;
    border-radius: 2px !important;
    background: var(--color-1) !important;
  }
}

/*! ======= 聊天区域 ======= */
#chat {
  align-items: center;
  background: none;
  border: none;
  scrollbar-width: thin;
  padding-bottom: var(--最新回复与输入框距离) !important;
}

#chat .mes:not(.smallSysMes) {
  position: relative;
  flex-direction: column;
  padding: 0;
  margin:20px auto;
  width: calc(100% - 0.8rem);

  .mes_block {
    overflow: visible;
    padding: 12px 0.5em;
    margin: 0;
    background: var(--color-1);
    box-shadow: 0 1px 2px var(--shadow-1);
    background-color: var(--SmartThemeChatTintColor);
    background-image: radial-gradient(rgba(122, 122, 122, 0.1) 1px, transparent 0);
    background-size: 15px 15px;
    background-position: -3px -3px;
  }

  .mes_text {
    padding: 0 2px;
    text-align: justify;
    p:not(blockquote p) {
      text-indent: 2em;
    }
    summary {
      text-align: center;
      list-style: none;
      color: var(--SmartThemeEmColor);
      margin-bottom: 1em;
    } 
    summary::-webkit-details-marker {
      display: none;
    }
  }

  .mes_reasoning_header {
    margin: 0;
    transform: translateY(-10px);
    aspect-ratio: 857/539;
      width: 5rem;
      height: auto;
      background: url('https://files.catbox.moe/bffzug.png')center / contain no-repeat;
    & .mes_reasoning_arrow {
      display: none;
    }
  }

  .mes_reasoning_header_title {
    font-size: 0;
  }

  @media (max-width: 768px) {
    .mes_reasoning_details {
      position: relative;
    }

    .mes_reasoning_details[open] {
      width: 100%;
    }

    .mes_reasoning {
      width: 100%;
      margin-bottom: 0.5em;
      max-height: 500px;
      overflow: hidden auto;
      scrollbar-width: thin;
      font-size: 0.95em;
    }

    .mes_reasoning_actions {
       position: absolute;
       right: 0.3rem;
       flex-shrink: 0;
    }
  }

  .mesAvatarWrapper {
    display: flex;
    align-items: center;
    position: relative;
    width: 100%;
    padding: 25px 8px !important;
    margin-bottom: 5px;
    gap: 15px;
    &::before {
      content: '';
      position: absolute;
      z-index: -1;
      bottom: 0;
      left: 50%;
      transform: translateX(-50%);
      width: 100%;
      height: 50px;
      border-radius: 2px;
      background: var(--pattern-1) center / 80px auto repeat;
      border: 2px solid var(--color-1);
      box-shadow: 1px 1px 0 0.5px var(--color-2);
  }
    &::after {
      content: '';
      position: absolute;
      top: calc(100% - 20px);
      left: 50%;
      transform: translateX(-50%);
      aspect-ratio: 590 / 70;
      width: 100%;
      background: url('https://files.catbox.moe/fk2c4v.png') center / contain no-repeat;
  }
}

  :is(.mesIDDisplay, .mes_timer, .tokenCounterDisplay):empty {
  display: none;
}

  .mesAvatarWrapper > div:not(.avatar) {
    opacity: 1;
    color: #fff;
    background: var(--color-3);
    padding: 0 3px;
    background-clip: text;
    -webkit-text-stroke: 2px transparent;
    transform: translateY(-100%);
  }

  .avatar {
  flex: 0 0 auto;
  transform: scale(1.25);
  margin-left: 20px;
  outline: 1.5px solid var(--color-1);
  box-shadow: 1px 1px 0 1.2px var(--color-2);
    & img {

    }
  }
}

  .mes_button,
  .mes_edit_buttons {
    filter: none !important;
    font-size: 0.95em;
  }

#chat .last_mes:not(.smallSysMes) {
  .mes_block {
    padding-bottom: 50px;
  }

  .swipe_right,
  .swipe_left {
    &::before {
      content: none;
    }
    opacity: 1;
    background-repeat: no-repeat;
    background-position: center;
    background-size: contain;
  }

  .swipe_left {
    display: flex;
    background-image: url('https://files.catbox.moe/lrfd6u.png');
    aspect-ratio: 785/556;
    width: 50px;
    height: auto;
    transform: translateY(calc(var(--swipeCounterHeight, 0px) + var(--swipeCounterMargin, 0px))) rotate(-5deg);
  }

  .swipe_right {
    background-image: url('https://files.catbox.moe/0il043.png');
    aspect-ratio: 615/238;
    width: 120px;
    height: auto;
  }
  .swipeRightBlock:not(.swipe_right) {
   pointer-events: none;
  }

  .swipeRightBlock {
    transform: translateY(calc(var(--swipeCounterHeight, 0px) + var(--swipeCounterMargin, 0px)));
    padding-right: 5px;
  }

  .swipes-counter {
    opacity: 1;
    color: #fff;
    background: var(--color-3);
    padding: 0 8px;
    background-clip: text;
    -webkit-text-stroke: 2px transparent;
    transform: translate(20px, 2px);
  }
}

