/*! ======= 文本美化 ======= */
q {
  border-radius: 15px;
  background: var(--SmartThemeUnderlineColor);
  box-shadow: inset 0 1px 4px 4px var(--color-1);
}

em,
.mes strong {
  color: var(--SmartThemeBodyColor) !important;
  text-decoration: underline;
  text-decoration-style: wavy;
  text-decoration-color: var(--SmartThemeEmColor);
}

code {
  border: 1.2px solid var(--color-1);
  color: #fff !important;
  border-radius: 1px;
  border: none;
  background: var(--SmartThemeUnderlineColor);
}

.mes .hljs {
  border-radius: 1px;
  background: rgba(255, 241, 214, 1);
  color: var(--SmartThemeBodyColor) !important;
